#include <iostream>

void bubbleSort(int arr[], int n) {
    bool swapped = true;
    int end = n - 1;

    // Traverse through all array elements
    while (swapped) {
        swapped = false;

        // Last I elements (from 0 to second last I)
        for (int i = 0; i < end; i++) {
            if (arr[i] > arr[i+1]) {
                // Swap arr[i] and arr[i+1]
