function determineMostRelevantProtocol(inputData) {
  let ipVersion = null;
  let transportLayerProtocol = null;
  let applicationLayerProtocol = null;

  // Analyze input data to determine IP version
  const sourceIpRegex = /^([\da-fA-F]{1,4}:){7}([\da-fA-F]{1,4})$/;
  const destIpRegex = /^([\da-fA-F]{1,4}:){7}([\da-fA-F]{1,4})$/;
  if (sourceIpRegex.test(inputData.sourceIP) && destIpRegex.test(inputData.destinationIP)) {
    ipVersion = 'ipv6';
  } else {
    ipVersion = 'ipv4';
  }

  // Determine transport layer protocol based on port number
  switch (inputData.port) {
    case 80:
      transportLayerProtocol = 'http';
      break;
    case 17:
      transportLayerProtocol = 'udp';
      break;
    default:
      transportLayerProtocol = 'tcp';
  }

  // Determine application layer protocol based on payload type
  const payloadRegex = /^[A-Za-z0-9 ]*$/; // Assuming application layer payload should only contain ASCII characters
  if (payloadRegex.test(inputData.payload)) {
    applicationLayerProtocol = 'http';
  }

  // Return protocol with highest relevance based on input data
  let mostRelevantProtocol = null;
  if (ipVersion === 'ipv6') {
    if (transportLayerProtocol !== null) {
      mostRelevantProtocol = transportLayerProtocol;
    } else if (applicationLayerProtocol !== null) {
      mostRelevantProtocol = applicationLayerProtocol;
    }
  } else {
    mostRelevantProtocol = transportLayerProtocol;
  }
  return mostRelevantProtocol;
}
